// // // // // // // // // // // // // // // // // // // // //             style={[styles.tab, activeTab === tab.id && styles.activeTab]}
// // // // // // // // // // // // // // // // // // // // //             onPress={() => setActiveTab(tab.id)}
// // // // // // // // // // // // // // // // // // // // //           >
// // // // // // // // // // // // // // // // // // // // //             <Text style={[styles.tabText, activeTab === tab.id && styles.activeTabText]}>
// // // // // // // // // // // // // // // // // // // // //               {tab.label}
// // // // // // // // // // // // // // // // // // // // //             </Text>
// // // // // // // // // // // // // // // // // // // // //             {activeTab === tab.id && <View style={styles.tabIndicator} />}
// // // // // // // // // // // // // // // // // // // // //           </TouchableOpacity>
// // // // // // // // // // // // // // // // // // // // //         ))}
